a.asgn_stat_cd = 'ACT' AND a.input_bgn_dt <= #{today}
AND a.input_end_dt >= #{today}
AND ((c.clnt_type_cd IN ('CUST','BOTH') AND p.cust_clnt_id = c.clnt_id)
  OR (c.clnt_type_cd IN ('VNDR','BOTH') AND d.blng_clnt_id = c.clnt_id))

mapper.select:
SELECT , FROM TB_BS_CLNT c LEFT JOIN TB_SY_CODE b ON b.code_grp_id = 'BANK' AND b.code = c.bank_cd
AND c.use_yn = #{filter.useYn}
AND c.clnt_type_cd IN ('CUST','BOTH') AND c.clnt_type_cd IN ('VNDR','BOTH') AND c.clnt_type_cd = #{filter.clientTypeCode}
AND (strpos(lower(c.clnt_nm), lower(#{filter.keyword})) > 0 OR strpos(c.biz_reg_no, #{filter.keyword}) > 0)
ORDER BY c.reg_dttm DESC, c.clnt_id

SELECT c.biz_reg_no FROM TB_BS_CLNT c WHERE c.clnt_nm = #{name}
AND c.clnt_id != #{excludedId}
ORDER BY c.biz_reg_no

mapper.update:
UPDATE TB_BS_CLNT SET use_yn=#{useYn}, mod_user_id=#{actor},
  mod_dttm=GREATEST(clock_timestamp(), COALESCE(mod_dttm,reg_dttm) + INTERVAL '1 microsecond')
WHERE clnt_id=#{version.clientId}
  AND mod_dttm IS NOT DISTINCT FROM #{version.modifiedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE}

mapper.select:
SELECT h.reg_dttm, h.chg_item_nm, h.bfr_val, h.aft_val, h.reg_user_id
FROM TB_SY_CHG_HIST h WHERE h.trgt_tbl_nm='TB_BS_CLNT' AND h.trgt_key=#{clientId}
ORDER BY h.reg_dttm DESC, h.hist_id DESC
